 "content": "from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            seen.add((r, c))
            q = [(r, c)]
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            out.append((color, cells))
    return out


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    objs = [(col, cells) for col, cells in components(g) if col != bg]

    # The long, edge-attached L is the color key and identifies the corner.
    edge_candidates = []
    for col, cells in objs:
        rs = [r for r,c in cells]
        cs = [c for r,c in cells]
        touches = [min(rs)==0, max(rs)==h-1, min(cs)==0, max(cs)==w-1]
        corners = []
        if touches[0] and touches[2]: corners.append('tl')
        if touches[0] and touches[3]: corners.append('tr')
        if touches[1] and touches[2]: corners.append('bl')
        if touches[1] and touches[3]: corners.append('br')
        for corner in corners:
            edge_candidates.append((len(cells), col, cells, corner))
    if not edge_candidates:
        return g
    _, key_color, key_cells, corner = max(edge_candidates, key=lambda x: x[0])
    opposite = {'tl':'br', 'tr':'bl', 'bl':'tr', 'br':'tl'}[corner]

    # In the diagonally opposite quadrant, recolor the nearest nontrivial object.
    def in_quadrant(r, c):
        if opposite == 'tl': return r < h/2 and c < w/2
        if opposite == 'tr': return r < h/2 and c >= w/2
        if opposite == 'bl': return r >= h/2 and c < w/2
        return r >= h/2 and c >= w/2
    candidates = []
    for col, cells in objs:
        if cells == key_cells:
            continue
        if len(cells) <= 1:
            continue
        if not any(in_quadrant(r,c) for r,c in cells):
            continue
        if opposite == 'tl': corner_cell = (0,0)
        elif opposite == 'tr': corner_cell = (0,w-1)
        elif opposite == 'bl': corner_cell = (h-1,0)
        else: corner_cell = (h-1,w-1)
        distance = min(abs(r-corner_cell[0])+abs(c-corner_cell[1]) for r,c in cells)
        candidates.append((distance, -len(cells), col, cells))
    if not candidates:
        return g
    _, _, _, target = min(candidates)
    for r, c in target:
        g[r][c] = key_color
    return g
